using LPLK.Common;
using System.Text;
using System.Text.Json;
using LPLK_Maps;
int count=0;void Check(bool ok,string message){count++;if(!ok)throw new Exception(message);}
void Reject(Action work,string name){bool rejected=false;try{work();}catch(Exception e)when(e is IOException or InvalidDataException or DecoderFallbackException){rejected=true;}Check(rejected,name);}
Check(ExtraWorkshopMapList.Parse("").Length==0,"Empty list");
Check(ExtraWorkshopMapList.Parse("# Kommentar\n// zweite Zeile\n  ").Length==0,"Comments");
Check(ExtraWorkshopMapList.Parse("\ufeff3539217452\r\n3442040035 # Fachwerk\r\n3539217452\n03442040035 // duplicate").SequenceEqual(new[]{"3442040035","3539217452"}),"BOM, Windows newlines, comments, canonical duplicates");
foreach(string bad in new[]{"0","-1","1 2","12.5","https://steamcommunity.com/sharedfiles/filedetails/?id=123","18446744073709551616","١٢٣","12;quit","12\0"})Reject(()=>ExtraWorkshopMapList.Parse(bad),"Reject unsafe ID");
Check(ExtraWorkshopMapList.Parse("18446744073709551615").Single()==ulong.MaxValue.ToString(),"UInt64 boundary");
Check(ExtraWorkshopMapList.Parse(string.Join('\n',Enumerable.Range(1,2000))).Length==2000,"2000 allowed");
Reject(()=>ExtraWorkshopMapList.Parse(string.Join('\n',Enumerable.Range(1,2001))),"Too many IDs");
Reject(()=>ExtraWorkshopMapList.Parse(new string('#',ExtraWorkshopMapList.MaximumBytes+1)),"Byte bound");
var merged=ExtraWorkshopMapList.Merge(["1","2"],["3"],[],["2","4"],[],false);
Check(merged.Ids.SequenceEqual(new[]{"1","2","3","4"}),"Collection plus manual plus file union");
Check(merged.FileOnly.SequenceEqual(new[]{"4"}),"Track only file-exclusive membership");
var removed=ExtraWorkshopMapList.Merge(["1","2","4"],["3"],[],[],merged.FileOnly,false);
Check(removed.Ids.SequenceEqual(new[]{"1","2","3","4"}),"Removing extra preserves collection-owned map");
var first=ExtraWorkshopMapList.Merge([],[],["1","2"],["2","3"],[],true);
Check(first.FileOnly.SequenceEqual(new[]{"3"}),"Seed overlaps kept");
var second=ExtraWorkshopMapList.Merge([],[],["1","2","3"],[],first.FileOnly,true);
Check(second.Ids.SequenceEqual(new[]{"1","2"}),"Removing file-only entry preserves original seed");
Reject(()=>ExtraWorkshopMapList.Merge(Enumerable.Range(1,2000).Select(x=>x.ToString()),[],[],["2001"],[],false),"Combined bound");
string directory=Path.Combine(Environment.GetEnvironmentVariable("LPLK_BUILD_ROOT")!,"ExtraWorkshopMapChecks/current");Directory.CreateDirectory(directory);string path=Path.Combine(directory,"workshop-extra-maps.txt");
File.WriteAllText(path,"12\n34\n",new UTF8Encoding(false));
var file=new ExtraWorkshopMapFile(path);file.Load();Check(file.Ids.SequenceEqual(new[]{"12","34"})&&file.Error is null,"Initial load");
Task<(string[]? Ids,string? Error)> Queue(Func<(string[]? Ids,string? Error)> work)=>Task.FromResult(work());
File.WriteAllText(path,"56\ninvalid\n");file.Poll(1,Queue);file.Poll(2,Queue);
Check(file.Error is not null&&file.Ids.SequenceEqual(new[]{"12","34"}),"Malformed edit preserves complete last accepted list");
File.WriteAllText(path,"56\n56\n");file.Poll(30002,Queue);Check(file.Poll(30003,Queue)&&file.Error is null&&file.Ids.SequenceEqual(new[]{"56"}),"Corrected edit applied without reload");
File.WriteAllText(path,"# empty again\n");file.Poll(60003,Queue);file.Poll(60004,Queue);Check(file.Ids.Length==0&&file.Error is null,"Empty edit clears extras");
File.WriteAllBytes(path,[0xff,0xff,0xff]);file.Poll(90004,Queue);file.Poll(90005,Queue);Check(file.Error is not null&&file.Ids.Length==0,"Invalid UTF8 retained safely");
File.WriteAllText(path,"# test completed\n");
var now=DateTimeOffset.Parse("2026-10-31T16:00:00+01:00");var markers=new NewMapMarkers();
Check(markers.Observe(["123","123","456"],now)&&markers.Snapshot().Count==2,"NEW deduplicates first observation");
Check(markers.IsNew("123",now)&&markers.IsNew("123",now.AddDays(14).AddTicks(-1)),"NEW starts at first observation and lasts fourteen days");
Check(!markers.IsNew("123",now.AddDays(14))&&!markers.IsNew("123",now.AddTicks(-1))&&!markers.IsNew("789",now),"Expired, future and unknown entries have no NEW label");
Check(!markers.Observe(["123"],now.AddDays(6))&&markers.Snapshot()["123"]==now,"Refresh does not extend NEW period");
var restored=NewMapMarkers.Parse(JsonSerializer.Serialize(markers.Snapshot()));
Check(restored.IsNew("123",now.AddDays(1))&&!restored.IsNew("123",now.AddDays(15)),"JSON reload preserves age");
string existing=MapPolicy.VoteLabel(new MapEntry{Id="123",Name="<b>unsafe</b>",MinPlayers=6,MaxPlayers=30},true);
string label=restored.Label("123",existing,now);
Check(label.StartsWith("<font color='#90EE90'><b>NEW</b></font> ")&&label.EndsWith(existing)&&!label.Contains("<b>unsafe"),"NEW preserves escaped name, limits and nomination marker");
Check(restored.Label("123",existing,now.AddDays(15))==existing,"Expiry preserves original label exactly");
var detached=restored.Snapshot();detached.Clear();Check(restored.IsNew("123",now),"Serialized snapshot cannot mutate live markers");
Reject(()=>restored.Observe(["bad;quit"],now),"Invalid marker IDs rejected");
Reject(()=>NewMapMarkers.Parse("null"),"Null marker file rejected");
var ordered=Enumerable.Range(1,20).Select(n=>new MapEntry{Id=n.ToString(),Name="Map "+n}).ToList();
var pageMarkers=new NewMapMarkers();pageMarkers.Observe(["16","17","18","19","20"],now);
var priority=pageMarkers.OrderNominations(ordered,now.AddDays(2));
Check(priority.Take(5).Select(m=>m.Id).SequenceEqual(new[]{"16","17","18","19","20"}),"All five new maps occupy the first five rows on page one");
Check(priority.Skip(5).SequenceEqual(ordered.Take(15)),"Existing order is preserved after new maps");
Check(pageMarkers.OrderNominations(ordered,now.AddDays(3)).SequenceEqual(ordered),"Original ordering returns exactly at expiry");
Check(pageMarkers.OrderNominations(ordered.Where(m=>m.Id!="17"),now).All(m=>m.Id!="17"),"Priority cannot reintroduce an ineligible map");
Check(pageMarkers.OrderNominations(ordered,now.AddTicks(-1)).SequenceEqual(ordered),"Future markers have no priority");
Check(NewMapMarkers.Parse(JsonSerializer.Serialize(pageMarkers.Snapshot())).OrderNominations(ordered,now.AddDays(2)).SequenceEqual(priority),"Reload preserves first-page priority and original deadline");
pageMarkers.Observe(["15"],now);
Check(pageMarkers.OrderNominations(ordered,now).Take(10).Count(m=>pageMarkers.IsNew(m.Id,now))==6,"Six requested new maps fit together on the ten-entry first page");
var builtinMarkers=new NewMapMarkers();builtinMarkers.Observe(["de_cbble","de_cache","123"],now);
var builtinReload=NewMapMarkers.Parse(JsonSerializer.Serialize(builtinMarkers.Snapshot()));
Check(builtinReload.IsNew("de_cbble",now.AddDays(13))&&builtinReload.IsNew("de_cache",now.AddDays(13)),"Built-in NEW markers survive reload");
Check(!builtinReload.IsNew("de_cbble",now.AddDays(14)),"Built-in NEW expires after fourteen days");
Check(!builtinReload.Observe(["de_cbble","de_cache"],now.AddDays(3))&&builtinReload.Snapshot()["de_cache"]==now,"Built-in refresh never extends deadline");
foreach(var bad in new[]{"de_cache;quit","../de_cbble","de_cache\n","_de","0","00123","workshop/123/de_cache"})Reject(()=>builtinReload.Observe([bad],now),"Unsafe built-in marker rejected");
var stock=new MapEntry{Id="de_cache",Name="Cache",InPool=true,Enabled=false,MinPlayers=6,MaxPlayers=20};
var removedStock=new MapEntry{Id="de_nuke",Name="Nuke",InPool=false};
var removedWorkshop=new MapEntry{Id="999",Name="removed",InPool=true};
var nextCatalog=WorkshopDetails.Merge([stock,removedStock,removedWorkshop],[]);
Check(nextCatalog.Single(m=>m.Id==stock.Id)==stock,"Workshop refresh preserves all built-in rules and manual disable");
Check(!nextCatalog.Single(m=>m.Id==removedStock.Id).InPool,"Workshop refresh cannot re-enable excluded built-in map");
Check(!nextCatalog.Single(m=>m.Id=="999").InPool,"Workshop removal still clears workshop membership");
Check(builtinReload.OrderNominations([removedStock,stock,new(){Id="123"}],now).Select(m=>m.Id).SequenceEqual(new[]{"de_cache","123","de_nuke"}),"Built-in and workshop NEW share first-page ordering");
var lifecycle=NewMapActivationState.Migrate(["de_dust2","123"],builtinReload,now);
Check(!lifecycle.Observe(["de_dust2","123","de_cache"],now.AddDays(1)),"Migration preserves established pool and legacy deadlines");
Check(lifecycle.Markers.Snapshot()["de_cache"]==now&&!lifecycle.Markers.IsNew("de_dust2",now),"Migration does not label old pool or restart legacy NEW");
foreach(var id in new[]{"surf_example","kz_example","de_future","987654321"})Check(lifecycle.Observe([id],now.AddDays(2)),"All map sources start automatically at first readiness: "+id);
var lifecycleReload=NewMapActivationState.Parse(JsonSerializer.Serialize(lifecycle.Snapshot()));
Check(!lifecycleReload.Observe(["de_future","123","de_dust2"],now.AddDays(20)),"Reload and re-add never restart first activation or baseline maps");
Check(lifecycleReload.Markers.IsNew("de_future",now.AddDays(16).AddTicks(-1))&&!lifecycleReload.Markers.IsNew("de_future",now.AddDays(16)),"Exact fourteen days from actual activation");
var snapshot=lifecycleReload.Snapshot();snapshot.BaselineIds[0]="de_fake";snapshot.ActivatedAt.Clear();
Check(!lifecycleReload.Observe(["123"],now)&&lifecycleReload.Markers.Snapshot().Count==7,"Activation snapshot is detached");
foreach(var invalid in new[]{"null",JsonSerializer.Serialize(new NewMapActivationState.Document(2,now,[],[])),JsonSerializer.Serialize(new NewMapActivationState.Document(1,now,["123","123"],[])),JsonSerializer.Serialize(new NewMapActivationState.Document(1,now,["../bad"],[])),JsonSerializer.Serialize(new NewMapActivationState.Document(1,default,[],[]))})Reject(()=>NewMapActivationState.Parse(invalid),"Invalid lifecycle fails closed");
if(args is ["--standard-plan",var planPath])
{
 using var receipt=JsonDocument.Parse(File.ReadAllText(planPath));using var plan=JsonDocument.Parse(receipt.RootElement.GetProperty("output").GetString()!);
 var proposals=plan.RootElement.GetProperty("maps").Deserialize<List<MapEntry>>()!;Check(proposals.Count==13,"Complete standard-map plan");
 foreach(var m in proposals)
 {
  var measured=MapPolicy.CaptureMeasurement(m,m.TSpawns!.Value,m.CtSpawns!.Value,m.BombSites!.Value,m.Hostages!.Value);
  Check(measured.LimitProposal==m.LimitProposal,"Remote proposal matches native C# formula and signature: "+m.Id);
  Check(!MapPolicy.LimitsUsable(m,new()),"Prepared plan cannot vote before approval: "+m.Id);
  var approved=MapPolicy.ApproveLimits(m,m.LimitProposal!.Signature);Check(MapPolicy.LimitsApproved(approved),"Reviewed signature approves exact range: "+m.Id);
  bool EligibleAt(int people)=>MapPolicy.Eligible([approved],"unrelated","",people,[],0).Count==1;
  Check(EligibleAt(approved.MinPlayers)&&EligibleAt(approved.MaxPlayers),"Both player boundaries eligible: "+m.Id);
  Check(!EligibleAt(approved.MinPlayers-1)&&!EligibleAt(approved.MaxPlayers+1),"Outside player boundaries excluded: "+m.Id);
 }
}
Console.WriteLine($"{count} ExtraWorkshopMapChecks passed");
